{
  "typography": {
    "caption": {
      "fontSize": {
        "pointer": 11,
        "touch": 11
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 16
      },
      "fontWeight": 500,
      "letterSpacing": 0.5
    },
    "detail": {
      "fontSize": {
        "pointer": 12,
        "touch": 12
      },
      "lineHeight": {
        "pointer": 16,
        "touch": 16
      },
      "fontWeight": 400,
      "letterSpacing": 0.4
    },
    "body": {
      "fontSize": {
        "pointer": 14,
        "touch": 14
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 400,
      "letterSpacing": 0.25
    },
    "label": {
      "fontSize": {
        "pointer": 14,
        "touch": 14
      },
      "lineHeight": {
        "pointer": 20,
        "touch": 20
      },
      "fontWeight": 500,
      "letterSpacing": 0.1
    },
    "title": {
      "fontSize": {
        "pointer": 16,
        "touch": 16
      },
      "lineHeight": {
        "pointer": 24,
        "touch": 24
      },
      "fontWeight": 500,
      "letterSpacing": 0.15
    },
    "headline": {
      "fontSize": {
        "pointer": 24,
        "touch": 24
      },
      "lineHeight": {
        "pointer": 32,
        "touch": 32
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "display": {
      "fontSize": {
        "pointer": 36,
        "touch": 36
      },
      "lineHeight": {
        "pointer": 44,
        "touch": 44
      },
      "fontWeight": 400,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "shape": {
      "control": "{radius-control}",
      "container": "{radius-container}",
      "modal": "{radius-modal}"
    },
    "size": {
      "hit": {
        "pointer": 44,
        "touch": 48
      },
      "density": {
        "pointer": {
          "pad": 16,
          "gap": 12,
          "surface": 12
        },
        "touch": {
          "pad": 16,
          "gap": 12,
          "surface": 16
        }
      },
      "control": {
        "pointer": {
          "padding": 8,
          "gap": 8,
          "dot": 10,
          "switch": "regular"
        },
        "touch": {
          "padding": 8,
          "gap": 8,
          "dot": 10,
          "switch": "regular"
        }
      },
      "height": {
        "pointer": {
          "sm": 32,
          "md": 40,
          "lg": 56
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 56
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "control": 1
    },
    "focus": {
      "style": "outline",
      "width": 3,
      "offset": 2
    },
    "icon": {
      "pointer": {
        "sm": 16,
        "md": 20,
        "lg": 24
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    }
  },
  "shape": {
    "curve": "circular",
    "corners": {
      "button": "full"
    }
  },
  "state": {
    "press-scale": 1,
    "overlay": {
      "hover": 0.08,
      "focus": 0.1,
      "pressed": 0.1,
      "dragged": 0.16
    },
    "ripple": true,
    "pressed-opacity": 1,
    "rest-opacity": 0.38,
    "disabled": {
      "content": 0.38,
      "fill": true
    }
  },
  "transition": {
    "enter": {
      "duration": 500,
      "timingFunction": "emphasized-decelerate"
    }
  },
  "motion": {
    "fast": {
      "stiffness": 800,
      "damping": 33.94
    },
    "default": {
      "stiffness": 380,
      "damping": 31.19
    },
    "slow": {
      "stiffness": 200,
      "damping": 22.63
    }
  },
  "controls": "material",
  "finishes": {
    "shared": {
      "card": {
        "background": "{card}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "material": {
          "android": {
            "elevation": 1
          }
        }
      },
      "inset": {
        "shadow": "none",
        "foreground": "{foreground}",
        "material": null
      },
      "raised": {
        "background": "{raised}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "backdropFilter": "none",
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "border-color": "transparent",
        "border-top-color": "transparent",
        "border-bottom-color": "transparent"
      },
      "overlay": {
        "background": "{popover}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "backdropFilter": "none",
        "material": {
          "android": {
            "elevation": 3
          }
        }
      },
      "modal": {
        "shadow": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "material": {
          "android": {
            "elevation": 6
          }
        }
      },
      "inverse": {
        "background": "{inverse}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)",
        "foreground": "{inverse-foreground}",
        "border-color": "transparent",
        "backdropFilter": "none",
        "material": {
          "android": {
            "elevation": 6
          }
        }
      },
      "glass": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "backdropFilter": "none",
        "material": {
          "android": {
            "elevation": 3
          }
        },
        "background": "{popover}"
      },
      "accent": {
        "background": "{primary}",
        "shadow": "none",
        "foreground": "{primary-foreground}",
        "border-color": "transparent",
        "border-top-color": "transparent",
        "border-bottom-color": "transparent",
        "material": null
      },
      "knob": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "material": null,
        "background": "{knob}",
        "border-color": "transparent"
      },
      "hover": {
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "{foreground}",
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "background": "{raised}",
        "border-color": "transparent",
        "border-top-color": "transparent",
        "border-bottom-color": "transparent"
      },
      "pressed": {
        "shadow": "none",
        "foreground": "{foreground}",
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "background": "{raised}",
        "border-color": "transparent",
        "border-top-color": "transparent",
        "border-bottom-color": "transparent"
      },
      "disabled": {
        "background": "oklch(from {foreground} l c h / 0.1)",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "foreground": "oklch(from {foreground} l c h / 0.38)",
        "border-color": "transparent",
        "material": null
      }
    },
    "light": {
      "modal": {
        "background": "oklch(0.93251 0.01479 312.24)"
      }
    },
    "dark": {
      "modal": {
        "background": "oklch(0.2859 0.01293 298.633)"
      }
    }
  },
  "elevation": {
    "light": {
      "sm": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "md": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "lg": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)",
      "xl": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)",
      "inset": null
    },
    "dark": {
      "sm": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "md": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
      "lg": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)",
      "xl": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)",
      "inset": null
    }
  }
}

{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "Material (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never delete finish fields or alter the merged finish key set across appearances or themes."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "Material 3 Expressive (`material-web` v34.0.21 / Compose Material 3 1.5.0) built from the `#6750A4` baseline with tonal surface containers, Expressive Tone 30 `on*Container` roles, state-layer overlays, and Expressive spatial/effects springs.",
        "elevation": "Tonal surface stepping plus Material Web Level 1–3 shadows and `material.android.elevation` (1dp/3dp/6dp), with no edge drawn (each finish's `border-color: transparent`) and no backdrop blur.",
        "dos": [
          "Express interaction states via M3 state-layer ink overlays (`hover: 0.08`, `focus: 0.10`, `pressed: 0.10`, `dragged: 0.16`) and Android press ripples (`state.ripple: true`) with `state.press-scale: 1`.",
          "Use `shape.curve: \"circular\"` and `controls: \"material\"` for top-rounded underlined fields and underlined tabs.",
          "Keep tonal and elevated containers edge-free through `border-color: transparent` in the finish, so depth comes from tonal steps and elevation."
        ],
        "donts": [
          "Do not add backdrop blur (`backdropFilter`) or a surface edge (`border-color`) to M3 tonal surfaces.",
          "Do not replace `outline` focus rings (`3px` width, `2px` offset) with halo rings."
        ]
      }
    }
  },
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 Fast Out, Slow In curve (entering elements)."
    },
    "accelerate": {
      "$value": [
        1,
        0,
        1,
        1
      ],
      "$description": "WinUI 3 Slow Out, Fast In curve (exiting elements)."
    },
    "point-to-point": {
      "$value": [
        0.55,
        0.55,
        0,
        1
      ],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "Material 3 Expressive typography scale (TypeScaleTokens.kt / _md-sys-typescale.scss).",
    "caption": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.caption}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0.5,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0.4,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
        "letterSpacing": {
          "value": 0.25,
          "unit": "px"
        }
      },
      "$description": "Standard body copy, list rows, and dialog content."
    },
    "label": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.label}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.label}",
        "letterSpacing": {
          "value": 0.1,
          "unit": "px"
        }
      },
      "$description": "Control labels, form labels, and interactive triggers."
    },
    "title": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.title}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.title}",
        "letterSpacing": {
          "value": 0.15,
          "unit": "px"
        }
      },
      "$description": "Card and section headings."
    },
    "headline": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.headline}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.headline}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Page-level headings."
    },
    "display": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.display}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.display}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Large display numerals and hero headings."
    }
  },
  "dimension": {
    "$type": "dimension",
    "$description": "Desktop pointer layout density, control geometry, and icon sizes.",
    "shape": {
      "$type": "dimension",
      "$description": "Semantic corner radius roles by layer, referencing base dimension.radius.* tokens.",
      "control": {
        "$value": "{dimension.radius.control}",
        "$description": "Corner radius for in-page elements: buttons, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": "{dimension.radius.container}",
        "$description": "Corner radius for containers and overlays: cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": "{dimension.radius.modal}",
        "$description": "Corner radius for modal surfaces: dialogs, sheets, and drawers."
      }
    },
    "stroke": {
      "$description": "Border stroke widths.",
      "hairline": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Hairline width for dividers, container edges (cards, drawers, overlays) and outlined variants."
      },
      "control": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Interactive control border width."
      }
    },
    "focus": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "style": "outline"
        }
      },
      "$description": "M3 focus indicator: 3px solid outline offset 2px (_md-sys-state-focus-indicator.scss).",
      "width": {
        "$value": {
          "value": 3,
          "unit": "px"
        },
        "$description": "Focus ring stroke width."
      },
      "offset": {
        "$value": {
          "value": 2,
          "unit": "px"
        },
        "$description": "2px outward focus indicator offset per M3."
      }
    },
    "radius": {
      "$type": "dimension",
      "$description": "Material 3 Expressive corner scale (Compose tokens at `ac364f3c`: 4px CornerExtraSmall control, 12px CornerMedium/CornerLarge container, 28px CornerExtraLarge modal; capsule buttons via `shape.corners.button: \"full\"`).",
      "control": {
        "$value": {
          "value": 4,
          "unit": "px"
        },
        "$description": "Corner radius for in-page controls, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": {
          "value": 12,
          "unit": "px"
        },
        "$description": "Corner radius for cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": {
          "value": 28,
          "unit": "px"
        },
        "$description": "Corner radius for dialogs, sheets, and drawers."
      }
    },
    "size": {
      "$description": "Ergonomic sizing scales for pointer input.",
      "hit": {
        "$value": {
          "value": 44,
          "unit": "px"
        },
        "$description": "Minimum hit target size (0 disables padding expansion)."
      },
      "density": {
        "$description": "Page-level padding, gap, and surface spacing metrics.",
        "pad": {
          "$value": {
            "value": 16,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        },
        "surface": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        }
      },
      "control": {
        "$extensions": {
          "dev.aning.shadcn-nsh": {
            "switch": "regular"
          }
        },
        "$description": "Control internal spacing and switch size tier.",
        "padding": {
          "$value": {
            "value": 8,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 8,
            "unit": "px"
          }
        },
        "dot": {
          "$value": {
            "value": 10,
            "unit": "px"
          }
        }
      },
      "height": {
        "$description": "Standard control heights (sm, md, lg).",
        "sm": {
          "$value": {
            "value": 32,
            "unit": "px"
          }
        },
        "md": {
          "$value": {
            "value": 40,
            "unit": "px"
          }
        },
        "lg": {
          "$value": {
            "value": 56,
            "unit": "px"
          }
        }
      }
    },
    "icon": {
      "$description": "Standard icon dimensions (sm, md, lg).",
      "sm": {
        "$value": {
          "value": 16,
          "unit": "px"
        }
      },
      "md": {
        "$value": {
          "value": 20,
          "unit": "px"
        }
      },
      "lg": {
        "$value": {
          "value": 24,
          "unit": "px"
        }
      }
    }
  },
  "shape": {
    "$description": "M3 circular arc corners (ShapeTokens.kt).",
    "$extensions": {
      "dev.aning.shadcn-nsh": {
        "curve": "circular",
        "corners": {
          "button": "full"
        }
      }
    }
  },
  "state": {
    "$type": "number",
    "$extensions": {
      "dev.aning.shadcn-nsh": {
        "ripple": true
      }
    },
    "$description": "Interaction state opacities, press scale, and ripple switch.",
    "press-scale": {
      "$value": 1,
      "$description": "Scale factor applied while pressed (1 disables press shrinking; M3 uses state layer + Android ripple)."
    },
    "overlay": {
      "$description": "M3 state-layer ink opacities: hover 0.08, focus 0.10, pressed 0.10, dragged 0.16 (StateTokens.kt).",
      "hover": {
        "$value": 0.08
      },
      "focus": {
        "$value": 0.1
      },
      "pressed": {
        "$value": 0.1
      },
      "dragged": {
        "$value": 0.16
      }
    },
    "pressed-opacity": {
      "$value": 1,
      "$description": "Content stays full opacity when pressed (1; ripple/state layer shows press)."
    },
    "rest-opacity": {
      "$value": 0.38,
      "$description": "Opacity a passive indicator sits at rest (a scrollbar's thumb), before the pointer is on it."
    },
    "disabled": {
      "$description": "M3 disabled controls: 0.38 content opacity with fill: true (10% onSurface container, _md-comp-button-filled.scss).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "fill": true
        }
      },
      "content": {
        "$value": 0.38
      }
    }
  },
  "transition": {
    "$type": "transition",
    "$description": "Named CSS/NSH transition presets.",
    "enter": {
      "$value": {
        "duration": {
          "value": 500,
          "unit": "ms"
        },
        "delay": {
          "value": 0,
          "unit": "ms"
        },
